<script setup>
/**
 * 族群等级编辑器（基础设定模块）
 *
 * 新增：4 套族群/势力等级模板一键套用
 *   - 修真·宗门等级
 *   - 西幻·王国贵族等级
 *   - 商业·财阀等级
 *   - 星际·文明等级
 */
import { computed } from 'vue'
import ChoicesEditor from '@/components/admin/ChoicesEditor.vue'
import { useChoicesStore } from '@/stores/choices'
import {
  getFactionLevelTemplateList,
  getFactionLevelTemplate,
} from '@/data/presetChoicesTemplates'

const choices = useChoicesStore()

const items = computed(() => choices.factionLevels)

/** 只读保护：数据库枚举值（后端 Faction.LEVEL_CHOICES） */
const readOnlyKeys = ['S', 'E', 'A', 'B', 'C', 'unknown']

/** 模板列表 */
const templates = computed(() => getFactionLevelTemplateList())
function getTemplateFn(key) {
  return getFactionLevelTemplate(key)
}

function onSave(list) {
  // 完整替换（列表内顺序已通过 weight 排序）
  choices.factionLevels.splice(0, choices.factionLevels.length, ...list)
}
</script>

<template>
  <ChoicesEditor
    title="族群等级"
    subtitle="族群势力的等级划分体系。修改后所有编辑器（族群、角色所属势力徽标、Dashboard 统计分组）会同步使用新名称和颜色。📜 已内置 4 套成熟模板可一键套用。"
    icon="🏛"
    accent-color="gold"
    :items="items"
    :read-only-keys="readOnlyKeys"
    :templates="templates"
    :get-template-fn="getTemplateFn"
    key-placeholder="例：S / E / A / B / C（英文、数字、下划线）"
    @save="onSave"
  />
